using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using WoWProbe;

internal static class RuntimeEvidenceTests
{
    static int passed,failed;static bool exportsOnly;static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
    static void Test(string name,Action test){if(exportsOnly&&name.IndexOf("export",StringComparison.OrdinalIgnoreCase)<0)return;try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
    static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
    static void Reject(Action action){try{action();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}catch(FormatException){return;}throw new Exception("expected rejection");}
    static string Temp(){string d=Path.Combine(Path.GetTempPath(),"wowprobe-evidence-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);return d;}
    static Dictionary<string,object> Read(string line){return (Dictionary<string,object>)Json.DeserializeObject(line);}
    static BattleTarget Target(string avatar){return new BattleTarget{Name="Reference",NameHash=TargetCatalog.HashName("Reference"),AvatarFile=avatar};}
    static OperationObservation Unknown(){return new OperationObservation{Fresh=false,Farm=new FarmObservation(),CorpseX=Double.NaN,CorpseY=Double.NaN};}
    static void MainCase(Action<string> test){string d=Temp();try{test(d);}finally{string full=Path.GetFullPath(d),expected=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar);string name=Path.GetFileName(full);Guid token;if(!String.Equals(Path.GetDirectoryName(full),expected,StringComparison.OrdinalIgnoreCase)||!name.StartsWith("wowprobe-evidence-tests-",StringComparison.Ordinal)||!Guid.TryParseExact(name.Substring("wowprobe-evidence-tests-".Length),"N",out token))throw new InvalidOperationException("Refusing test cleanup outside its verified temporary directory.");Directory.Delete(full,true);}}
    static int Main(string[] args)
    {
        exportsOnly=args.Length==1&&args[0]=="--export-only";
        Test("simulation journal writes valid JSONL with unknown-safe state and zero native input",delegate{MainCase(delegate(string d){using(var j=new RunJournal(d,true)){j.Record("Waiting","unknown",Unknown(),null,123);}var files=Directory.GetFiles(d,"run-*.jsonl");Check(files.Length==1,"one dated journal");var rows=File.ReadAllLines(files[0],Encoding.UTF8);Check(rows.Length==2,"header plus record");var record=Read(rows[1]);Check(Equals(record["source"],"simulation")&&Convert.ToInt32(record["native_input_events"])==0,"simulation source");var state=(Dictionary<string,object>)record["observation"];Check(state["x"]==null&&state["health"]==null&&state["corpse_x"]==null,"unknowns serialized as null");Check(!Convert.ToBoolean(state["fresh"]),"unknown freshness retained");Check(Convert.ToInt64(record["virtual_milliseconds"])==123,"virtual time");});});
        Test("live journal never asserts zero emitted native input",delegate{MainCase(delegate(string d){using(var j=new RunJournal(d,false)){j.Record("LiveAttempt","pending",null,null,0);}var row=Read(File.ReadAllLines(Directory.GetFiles(d,"run-*.jsonl")[0])[1]);Check(Equals(row["source"],"live_observation")&&row["native_input_events"]==null,"live input cannot be claimed zero");});});
        Test("planned command and item evidence retain expected identity and inventory revision",delegate{MainCase(delegate(string d){var o=Unknown();o.InventoryRevision=22;o.InventoryEventsKnown=true;o.Item=new InventoryItem{Known=true,ItemId=17,Fingerprint=99,Count=3,Quality=0,UnitPrice=7,QuestKnown=true,TypeKnown=true};var c=new OperationCommand{Action=OperationAction.RightClick,Purpose=OperationPurpose.Sell,ExpectedItemId=17,ExpectedItemFingerprint=99,ExpectedInventoryRevision=22,ExpectedItemCount=3,Bag=1,Slot=2,Region=new Rectangle(10,20,30,40),HoldMilliseconds=120};using(var j=new RunJournal(d,true)){j.Record("Sell","planned",o,c,1000);}var row=Read(File.ReadAllLines(Directory.GetFiles(d,"run-*.jsonl")[0])[1]);var command=(Dictionary<string,object>)row["command"];Check(Equals(command["kind"],"planned_command")&&Convert.ToInt32(command["expected_item_id"])==17&&Convert.ToInt32(command["expected_inventory_revision"])==22,"planned evidence");});});
        Test("negative virtual time and use after disposal are rejected",delegate{MainCase(delegate(string d){var j=new RunJournal(d,true);Reject(delegate{j.Record("x","",null,null,-1);});j.Dispose();j.Dispose();try{j.Record("x","",null,null,0);throw new Exception("disposed journal accepted record");}catch(ObjectDisposedException){} });});
        Test("snapshots are PNG files and do not take ownership of caller bitmap",delegate{MainCase(delegate(string d){using(var j=new RunJournal(d,true))using(var bitmap=new Bitmap(4,4)){bitmap.SetPixel(0,0,Color.Red);string file=j.SaveSnapshot(bitmap,"death");Check(File.Exists(file)&&Path.GetFileName(file).StartsWith("snapshot-"),"snapshot file");using(var copy=new Bitmap(file))Check(copy.GetPixel(0,0).ToArgb()==Color.Red.ToArgb(),"PNG pixels");bitmap.SetPixel(1,1,Color.Blue);}});});
        Test("retention removes only owned dated outputs and never recurses or deletes user files",delegate{MainCase(delegate(string d){var now=new DateTime(2026,11,1,1,2,3,DateTimeKind.Utc);string oldLog,oldSnapshot;using(var j=new RunJournal(d,true,delegate{return now;}))using(var bitmap=new Bitmap(1,1)){j.Record("old","",null,null,0);oldSnapshot=j.SaveSnapshot(bitmap,"old");oldLog=Directory.GetFiles(d,"run-*.jsonl")[0];}File.WriteAllText(Path.Combine(d,"notes.jsonl"),"user");File.WriteAllText(Path.Combine(d,"run-user-data.jsonl"),"user");File.WriteAllText(Path.Combine(d,"snapshot-family.png"),"user");Directory.CreateDirectory(Path.Combine(d,"nested"));string nested=Path.Combine(d,"nested",Path.GetFileName(oldLog));File.Copy(oldLog,nested);now=now.AddMinutes(31);using(var j=new RunJournal(d,true,delegate{return now;})){}Check(!File.Exists(oldSnapshot)&&File.Exists(oldLog),"30min snapshots versus7day logs");now=now.AddDays(8);using(var j=new RunJournal(d,true,delegate{return now;})){}Check(!File.Exists(oldLog),"7day log retention");Check(File.ReadAllText(Path.Combine(d,"notes.jsonl"))=="user"&&File.Exists(Path.Combine(d,"run-user-data.jsonl"))&&File.Exists(Path.Combine(d,"snapshot-family.png"))&&File.Exists(nested),"unrelated or nested outputs deleted");});});
        Test("concurrent journal records remain separate complete JSON lines",delegate{MainCase(delegate(string d){using(var j=new RunJournal(d,true)){var workers=new List<Thread>();for(int i=0;i<4;i++){var t=new Thread(delegate(){for(int n=0;n<20;n++)j.Record("Thread","line",null,null,n);});workers.Add(t);t.Start();}foreach(var t in workers)t.Join();}int records=0;foreach(string line in File.ReadAllLines(Directory.GetFiles(d,"run-*.jsonl")[0])){Read(line);records++;}Check(records==81,"concurrent records interleaved or lost");});});
        Test("log files rotate before ten MiB without dropping records",delegate{MainCase(delegate(string d){using(var j=new RunJournal(d,true)){for(int i=0;i<1500;i++)j.Record("Long",new string('x',8192),null,null,i);}int records=0;var files=Directory.GetFiles(d,"run-*.jsonl");Check(files.Length>=2,"large log did not rotate");foreach(string path in files){Check(new FileInfo(path).Length<=10L*1024*1024,"log exceeded ten MiB");records+=File.ReadAllLines(path).Length-1;}Check(records==1500,"rotation lost records");});});
        Test("export copies current run outputs with an explicit pending validation manifest",delegate{MainCase(delegate(string d){string export=Path.Combine(d,"export");using(var j=new RunJournal(d,true))using(var bitmap=new Bitmap(1,1)){j.Record("Snapshot","",null,null,10);j.SaveSnapshot(bitmap,"snapshot");j.Export(export);}Check(Directory.GetFiles(export,"run-*.jsonl").Length==1&&Directory.GetFiles(export,"snapshot-*.png").Length==1,"export output set");var m=Read(File.ReadAllText(Path.Combine(export,"runtime-evidence.json")));Check(Equals(m["game_validation"],"pending")&&Equals(m["source"],"simulation"),"manifest mislabels live validation");});});
        Test("exported snapshot references resolve to byte-identical PNG files",delegate{MainCase(delegate(string d){string export=Path.Combine(d,"report");using(var j=new RunJournal(d,true))using(var bitmap=new Bitmap(3,2)){bitmap.SetPixel(1,1,Color.CornflowerBlue);string source=j.SaveSnapshot(bitmap,"keyframe");byte[] expected=File.ReadAllBytes(source);j.Export(export);var m=Read(File.ReadAllText(Path.Combine(export,"runtime-evidence.json")));var metadata=(Dictionary<string,object>)((object[])m["snapshots"])[0];string copied=Path.Combine(export,(string)metadata["file"]);Check(File.Exists(copied),"manifest keyframe file missing");Check(Convert.ToBase64String(expected)==Convert.ToBase64String(File.ReadAllBytes(copied)),"snapshot was reencoded or corrupted during export");}});});
        Test("export excludes expired snapshots unrelated images and another run's files",delegate{MainCase(delegate(string d){DateTime now=new DateTime(2026,11,1,0,0,0,DateTimeKind.Utc);string export=Path.Combine(d,"report");using(var j=new RunJournal(d,true,delegate{return now;}))using(var bitmap=new Bitmap(2,2)){string expired=j.SaveSnapshot(bitmap,"expired");now=now.AddMinutes(20);string current=j.SaveSnapshot(bitmap,"current");string personal=Path.Combine(d,"personal.png");bitmap.Save(personal,System.Drawing.Imaging.ImageFormat.Png);using(var other=new RunJournal(d,false,delegate{return now;})){other.Record("other","",null,null,0);}now=now.AddMinutes(11);Check(File.Exists(expired),"setup must retain old snapshot until export performs pruning");
            j.Export(export);Check(!File.Exists(expired)&&!File.Exists(Path.Combine(export,Path.GetFileName(expired)))&&File.Exists(Path.Combine(export,Path.GetFileName(current))),"expired/current snapshot set");Check(!File.Exists(Path.Combine(export,"personal.png"))&&File.Exists(personal),"unrelated image copied or deleted");Check(Directory.GetFiles(export,"run-*.jsonl").Length==1,"another run log exported");var m=Read(File.ReadAllText(Path.Combine(export,"runtime-evidence.json")));Check(((object[])m["snapshots"]).Length==1,"expired snapshot retained in manifest");}});});
        Test("export fails closed for a source outside the owned journal directory",delegate{MainCase(delegate(string d){string journal=Path.Combine(d,"journal"),external=Path.Combine(d,"private.txt"),export=Path.Combine(d,"report");File.WriteAllText(external,"private");using(var j=new RunJournal(journal,true)){var written=(List<string>)typeof(RunJournal).GetField("written",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(j);written.Add(external);Reject(delegate{j.Export(export);});Check(!File.Exists(Path.Combine(export,"private.txt")),"outside source copied");Check(File.ReadAllText(external)=="private","outside source changed");}});});
        Test("owned output count stays bounded while unrelated matching-name text survives",delegate{MainCase(delegate(string d){string unrelated=Path.Combine(d,"run-20200101-000000000-"+Guid.NewGuid().ToString("N")+"-000001.jsonl");File.WriteAllText(unrelated,"user data without tool ownership header");using(var j=new RunJournal(d,true))using(var bitmap=new Bitmap(1,1)){for(int i=0;i<1002;i++)j.SaveSnapshot(bitmap,"bounded");Check(Directory.GetFiles(d,"snapshot-*.png").Length==999,"snapshot/log total exceeded1000");Check(File.ReadAllText(unrelated)=="user data without tool ownership header","unrelated tool-shaped text removed");j.Export(Path.Combine(d,"export"));var m=Read(File.ReadAllText(Path.Combine(d,"export","runtime-evidence.json")));Check(((object[])m["snapshots"]).Length==999,"pruned snapshot metadata retained");}});});
        Test("filesystem export failures propagate to the caller",delegate{MainCase(delegate(string d){string blocked=Path.Combine(d,"blocked");File.WriteAllText(blocked,"user");using(var j=new RunJournal(d,true)){bool caughtIo=false;try{j.Export(blocked);}catch(IOException){caughtIo=true;}Check(caughtIo,"I/O failure was hidden");Check(File.ReadAllText(blocked)=="user","unrelated export target overwritten");}});});
        Test("portrait color score distinguishes opposite synthetic images and accepts resized references",delegate{using(var a=new Bitmap(32,32))using(var b=new Bitmap(64,64))using(var opposite=new Bitmap(32,32)){using(var g=Graphics.FromImage(a)){g.Clear(Color.Black);g.FillRectangle(Brushes.White,0,0,16,32);}using(var g=Graphics.FromImage(b)){g.Clear(Color.Black);g.FillRectangle(Brushes.White,0,0,32,64);}using(var g=Graphics.FromImage(opposite)){g.Clear(Color.White);g.FillRectangle(Brushes.Black,0,0,16,32);}Check(PortraitMatcher.Compare(a,a)>.999,"identical portrait");Check(PortraitMatcher.Compare(a,b)>.95,"resized portrait");Check(PortraitMatcher.Compare(a,opposite)<.15,"opposite portrait false match");}});
        Test("portrait comparison rejects null and oversized images",delegate{using(var a=new Bitmap(1,1))using(var large=new Bitmap(513,1)){Reject(delegate{PortraitMatcher.Compare(null,a);});Reject(delegate{PortraitMatcher.Compare(a,large);});}});
        Test("reference loading is detached bounded and restricted to validated avatars paths",delegate{MainCase(delegate(string d){Directory.CreateDirectory(Path.Combine(d,"avatars"));using(var image=new Bitmap(5,6))image.Save(Path.Combine(d,"avatars","ref.png"),System.Drawing.Imaging.ImageFormat.Png);using(var loaded=PortraitMatcher.LoadReference(d,Target("avatars/ref.png"))){File.Delete(Path.Combine(d,"avatars","ref.png"));Check(loaded.Width==5&&loaded.Height==6,"reference stream remains locked");}Reject(delegate{PortraitMatcher.LoadReference(d,Target("../secret.png"));});File.WriteAllBytes(Path.Combine(d,"avatars","large.png"),new byte[1024*1024+1]);Reject(delegate{PortraitMatcher.LoadReference(d,Target("avatars/large.png"));});});});
        Test("reference PNG dimensions are checked before decoding a compressed image",delegate{MainCase(delegate(string d){Directory.CreateDirectory(Path.Combine(d,"avatars"));byte[] bytes=new byte[33];byte[] signature={137,80,78,71,13,10,26,10};Buffer.BlockCopy(signature,0,bytes,0,8);bytes[11]=13;bytes[12]=73;bytes[13]=72;bytes[14]=68;bytes[15]=82;bytes[18]=16;bytes[23]=1;File.WriteAllBytes(Path.Combine(d,"avatars","bomb.png"),bytes);Reject(delegate{PortraitMatcher.LoadReference(d,Target("avatars/bomb.png"));});});});
        Console.WriteLine("Runtime evidence tests: "+passed+" passed, "+failed+" failed. Local temporary files and synthetic images only.");return failed==0?0:1;
    }
}
